const C = { ink:hex('#111111'), sec:hex('#707072'), bg:hex('#FFFFFF'), surf:hex('#F6F6F6'), line:hex('#E5E5E5'), err:hex('#D43F21'), warn:hex('#9E3500'), dark:hex('#0A0A0A'), darkSurf:hex('#1E1E1E'), darkLine:hex('#3A3A3A'), onDarkSec:hex('#A5A5A5'), white:hex('#FFFFFF') };
