async function instanceOf(id, parent, x, y, name){
  const srcN = await S(id);
  const inst = srcN.createInstance();
  parent.appendChild(inst);
  inst.x = x; inst.y = y;
  if (name) inst.name = name;
  return inst;
}
function txt(chars, o={}){
  const t = figma.createText();
  t.fontName = {family:'Inter', style:o.style||'Regular'};
  t.fontSize = o.size||15;
  if (o.lh) t.lineHeight = {value:o.lh, unit:'PIXELS'};
  if (o.ls !== undefined) t.letterSpacing = {value:o.ls, unit:'PIXELS'};
  t.characters = chars;
  t.fills = solid(o.color||C.ink);
  if (o.w){ t.textAutoResize='HEIGHT'; t.resize(o.w, t.height); }
  if (o.name) t.name = o.name;
  return t;
}
function rect(w,h,color,radius=0,name){
  const r = figma.createRectangle(); r.resize(w,h); r.fills=solid(color);
  if (radius) r.cornerRadius = radius; if (name) r.name = name;
  return r;
}
function makeFrame(name, x, y, w, h, bg){
  const f = figma.createFrame();
  f.name = name; f.x = x; f.y = y; f.resize(w,h);
  f.fills = solid(bg); f.clipsContent = true;
  page.appendChild(f);
  return f;
}
async function statusBar(f){
  const sb = await S('1:32');
  const inst = sb.createInstance(); f.appendChild(inst); inst.x=0; inst.y=0; inst.name='Status Bar';
  return inst;
}
async function homeInd(f){
  const hi = await S('1:42');
