const page = await figma.getNodeByIdAsync('3:2');
const all = [];
function walk(node){ all.push(node); if('children' in node) node.children.forEach(walk); }
page.children.forEach(walk);
// Count frames with reactions
const frames = page.children.filter(n=>n.type==='FRAME');
let wiredFrames = 0, totalReactions = 0;
for(const f of frames){
  let count=0;
  function r(n){ if(n.reactions && n.reactions.length) count += n.reactions.length; if('children' in n) n.children.forEach(r); }
  r(f);
  if(count>0) wiredFrames++;
  totalReactions += count;
}
// Count components
const comps = page.children.filter(n=>n.type==='COMPONENT');
return JSON.stringify({
  frameCount: frames.length,
  frameNames: frames.map(f=>f.name),
  wiredFrames,
  totalReactions,
  componentCount: comps.length,
  componentNames: comps.map(c=>c.name)
}, null, 1);

